        <a href="@($"recipe/{CategoryName}/{recipe.Slug}")" class="list-group-item list-group-item-action">
            <div class="d-flex w-100 justify-content-between">
                <h5 class="mb-1">@recipe.Title</h5>
                <small>@recipe.PrepTime</small>
            </div>
            <p class="mb-1">@recipe.Description</p>
        </a>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = "";

    private string GetCategoryDisplayName() => CategoryName?.ToLower() switch
    {
        "breakfast" => "🥞 Breakfast Recipes",
        "lunch" => "🥗 Lunch Recipes",
        "dinner" => "🍝 Dinner Recipes",
