            new("Grilled Cheese", "grilled-cheese", "Golden, melty comfort food.", "10 min"),
            new("Chicken Wrap", "chicken-wrap", "Seasoned chicken with fresh veggies.", "20 min")
        },
        "dinner" => new()
        {
            new("Spaghetti Bolognese", "spaghetti-bolognese", "Rich meat sauce over al dente pasta.", "45 min"),
            new("Grilled Salmon", "grilled-salmon", "Herb-crusted salmon with lemon.", "30 min"),
            new("Chicken Stir Fry", "chicken-stir-fry", "Quick and colorful weeknight dinner.", "25 min")
        },
        "desserts" => new()
        {
            new("Chocolate Cake", "chocolate-cake", "Moist, rich, and deeply chocolatey.", "60 min"),
            new("Apple Pie", "apple-pie", "Classic homestyle with flaky crust.", "90 min"),
            new("Tiramisu", "tiramisu", "Italian coffee-flavored layered dessert.", "40 min")
        },
        "drinks" => new()
        {
            new("Berry Smoothie", "berry-smoothie", "Blended mixed berries with yogurt.", "5 min"),
            new("Iced Latte", "iced-latte", "Cold espresso with creamy milk.", "5 min"),
            new("Lemonade", "lemonade", "Fresh-squeezed with a hint of mint.", "10 min")
        },
        "snacks" => new()
        {
            new("Guacamole", "guacamole", "Chunky avocado dip with lime.", "10 min"),
            new("Hummus", "hummus", "Smooth chickpea dip with tahini.", "15 min"),
            new("Trail Mix", "trail-mix", "Nuts, seeds, and dried fruit.", "5 min")
        },
        _ => new()
    };

    private record RecipeSummary(string Title, string Slug, string Description, string PrepTime);
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Thank you!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been submitted for review.</p>
        <button class="btn btn-primary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Model.Ingredients" />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps" />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private void ResetForm()
    {
        Model = new();
        IsSubmitted = false;
    }

    private class RecipeSubmission
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

